const o=[["passed","Passed"],["failed","Failed"],["blocked","Blocked"],["running","Running"],["pending","Pending"],["paused","Paused"],["aborted","Aborted"],["skipped","Skipped"],["not_applicable","Not applicable"],["unknown","Unknown"]];function i(e){const n=new Map(o.map(([t])=>[t,0]));for(const t of e){const a=String(t.status||"").trim().toLowerCase(),s=n.has(a)?a:"unknown";n.set(s,(n.get(s)||0)+1)}return{total:e.length,segments:o.map(([t,a])=>({key:t,label:a,count:n.get(t)||0}))}}function u(e){if(e===null||!Number.isFinite(e))return;const n=Math.max(0,Math.min(100,e));return{total:100,unit:"percent",segments:[{key:"covered",label:"Readiness score",count:n},{key:"pending",label:"Remaining score",count:100-n}]}}export{i as a,u as b};
